function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function renderFeed(scroll=false){const list=$('#message-list');if(!list)return;const filtered=state.feed.filter(m=>activeChannel==='all'||m.channel===activeChannel);if(!filtered.length){list.innerHTML='<div class="no-messages">NO MESSAGES YET — THE CHANNEL IS QUIET.</div>';return;}let prev='';list.innerHTML=filtered.map(m=>{const p=people[m.person]||people.ada;const divider=m.time?.startsWith('08:')&&Number(m.time.slice(3))<21?'TODAY':'SHIFT '+String(state.day).padStart(2,'0');let out='';if(divider!==prev){out+=`<div class="day-divider">${divider}</div>`;prev=divider;}out+=`<article class="message ${m.system?'system ':''}${m.custom?'is-new':''}"><div class="message-avatar ${p.tone}">${p.initials}</div><div><div class="message-line"><strong>${escapeHTML(p.name)}</strong><span class="role">${p.role}</span><time>${escapeHTML(m.time)}</time></div><p class="message-copy">${escapeHTML(m.text)}</p>${m.reaction?`<div class="message-reaction"><span class="reaction">${escapeHTML(m.reaction)}</span></div>`:''}</div></article>`;return out;}).join('');if(scroll)list.scrollTop=list.scrollHeight;$('#all-count').textContent=String(state.feed.filter(m=>m.channel==='all'||m.channel==='shelter'||m.channel==='transit'||m.channel==='civic').length).padStart(2,'0');}
function updateChannel(){const [title,desc]=channels[activeChannel];$('#channel-title').textContent=title;$('#channel-description').textContent=desc;document.querySelectorAll('.channel-tab').forEach(b=>b.classList.toggle('active',b.dataset.channel===activeChannel));renderFeed(true);}
function statMood(key,value){if(key==='order')return value>75?'Stable, watchful':value>45?'Uneasy, holding':'Tensions are rising';if(key==='welfare')return value>70?'Needs are being met':value>45?'Needs are going unmet':'Residents are struggling';if(key==='trust')return value>70?'Confidence is growing':value>43?'Listening, not convinced':'Confidence is fraying';return value>70?'Reserve levels steady':value>40?'Ration stock: 3 days':'Reserve is running low';}
function paintStats(){for(const key of ['order','welfare','trust','supply']){const value=state.stats[key];$(`#${key}-value`).textContent=value;$(`#${key}-meter`).style.width=`${value}%`;$(`#${key}-note`).textContent=statMood(key,value);const delta=state.lastDelta?.[key]||0;const tag=$(`#${key}-trend`);tag.textContent=`${delta>0?'+':''}${delta}`;tag.classList.toggle('vitals-alert',delta<0);}$('#shift-number').textContent=String(state.day).padStart(2,'0');$('#shift-name').textContent=['Morning watch','Midday review','Afternoon watch','Evening watch','Night report','Dawn briefing','Final council'][Math.min(state.day-1,6)];$('#shift-date').textContent=['MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY','SUNDAY'][Math.min(state.day-1,6)]+' · 17 MAY';$('#top-date').textContent=`DAY ${String(state.day).padStart(2,'0')} · 08:${String(16+state.day*3).padStart(2,'0')}`;$('#shift-progress').style.width=`${Math.max(0,((state.day-1)/7)*100)}%`;$('#days-left').textContent=`${Math.max(0,8-state.day)} SHIFTS LEFT`;$('#footer-clock').textContent=`08:${String(messageClock).padStart(2,'0')}:42 • LOCAL`;$('#online-count').textContent=String(5+((state.day*7)%4)).padStart(2,'0');}
function renderDirectives(){const list=$('#directive-list');list.innerHTML=directives.map(d=>{const used=state.used.includes(d.id);const scarce=state.stats.supply<d.cost;return `<article class="directive ${used?'chosen':''} ${scarce&&!used?'disabled':''}"><div class="directive-main"><span class="directive-icon">${d.icon}</span><div class="directive-text"><h3>${d.title}</h3><p>${d.description}</p></div><div class="directive-side"><span class="directive-cost">−${d.cost} RESERVE</span><span class="directive-effect">${d.impact}</span></div></div><button class="directive-button" data-directive="${d.id}" ${used||scarce||state.ended?'disabled':''}>${used?'DIRECTIVE ISSUED':scarce?'INSUFFICIENT RESERVE':'ISSUE DIRECTIVE'} <span>${used?'✓':'→'}</span></button></article>`;}).join('');const left=directives.length-state.used.length;$('#actions-left').textContent=`0${left} AVAILABLE`;$('#docket-status').textContent=state.ended?'SIMULATION COMPLETE':`${left} DIRECTIVE${left===1?'':'S'} READY`;$('#end-shift').disabled=state.ended;}
function renderIncident(){if(state.day===1)return;const event=state.currentEvent||eventPool[(state.day-2)%eventPool.length];$('#incident-title').textContent=event.title;$('#incident-copy').textContent=event.copy;const p=people[event.who]||people.mara;$('.source-avatar').textContent=p.initials;$('.incident-source strong').textContent=p.name;$('.incident-source small').textContent=`${p.role} · JUST NOW`;$('.incident-kicker span:last-child').textContent=`08:${String(12+state.day*2).padStart(2,'0')} LOCAL`;}
function render(){paintStats();renderDirectives();renderIncident();renderFeed();if(state.ended)showEnding();}
function showToast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2500);}
function addStats(effects){for(const k of Object.keys(state.stats))state.stats[k]=clamp(state.stats[k]+(effects[k]||0));state.lastDelta={...effects};}
function issueDirective(id){const d=directives.find(x=>x.id===id);if(!d||state.used.includes(id)||state.ended)return;if(state.stats.supply<d.cost){showToast('Not enough reserve to issue this directive.');return;}state.used.push(id);addStats(d.effects);addMessage(makeMsg('ada',d.msg,{channel:'civic',custom:true}),true);const reactions={water:['mara','That will help. I will get the landing volunteers ready.'],patrol:['eli','Understood. I will keep the platform clear and report what I see.'],assembly:['orren','I will put out word. People have been waiting to be heard.']};const [who,text]=reactions[id];setTimeout(()=>addMessage(makeMsg(who,text,{channel:people[who].channel,custom:true}),true),650);render();save();showToast(`${d.title} — directive issued.`);}
function chooseLine(){const s=state.stats;const keys=[];if(s.welfare<42)keys.push('lowWelfare');if(s.welfare>70)keys.push('highWelfare');if(s.order<42)keys.push('lowOrder');if(s.order>76)keys.push('highOrder');if(s.trust<35)keys.push('lowTrust');if(s.trust>65)keys.push('highTrust');if(s.supply<35)keys.push('lowSupply');if(s.supply>76)keys.push('highSupply');if(!keys.length)keys.push(['lowTrust','lowWelfare','highOrder'][state.day%3]);const group=lines[keys[Math.floor(Math.random()*keys.length)]];return group[Math.floor(Math.random()*group.length)];}
function autonomousMessage(){if(state.ended)return;const [who,text]=Math.random()<.73?chooseLine():ambientLines[Math.floor(Math.random()*ambientLines.length)];messageClock+=2+Math.floor(Math.random()*4);addMessage(makeMsg(who,text,{custom:true}),true);$('#typing-text').textContent=`${people[who].name} is typing…`;setTimeout(()=>$('#typing-text').textContent='Residents are checking in…',2000);}
function bulletinReply(text){const normalized=text.toLowerCase();let who='mara',reply='We have seen the notice. Let us know what happens next.';if(/water|pump|pressure|shelter/.test(normalized)){who='noa';reply='I will pass this along at Shelter 12. People are waiting on a real update.';}else if(/patrol|safe|safety|transit/.test(normalized)){who='eli';reply='I will relay this to the platform crew. We will keep the line moving.';}else if(/meeting|assembly|listen|question|feedback/.test(normalized)){who='orren';reply='I will add that to the civic board. People appreciate being asked.';}else if(/ration|food|supply|market/.test(normalized)){who='tess';reply='I will tell the market. A clear schedule makes a big difference.';}else if(/clinic|health|medicine/.test(normalized)){who='june';reply='Thank you for answering. I will update the clinic queue.';}else if(/thank|sorry|together|help/.test(normalized)){who='mara';reply='We hear you. Showing up matters more than a perfect speech.';}return [who,reply];}
function sendBulletin(event){event.preventDefault();const input=$('#message-input');const text=input.value.trim();if(!text||state.ended)return;if(state.bulletins>=2){showToast('Two public bulletins per shift. Save the channel for what matters.');return;}state.bulletins++;state.stats.trust=clamp(state.stats.trust+2);state.lastDelta.trust=2;addMessage(makeMsg('ada',text,{channel:'all',custom:true}),true);input.value='';render();const [who,reply]=bulletinReply(text);setTimeout(()=>addMessage(makeMsg(who,reply,{channel:people[who].channel,custom:true}),true),900);showToast('Bulletin sent · residents will respond.');}
function endShift(){if(state.ended)return;const prior={...state.stats};let effects={order:-2,welfare:-1,trust:0,supply:-3};if(state.stats.order<40)effects.order-=3;if(state.stats.welfare<35)effects.order-=1;if(state.stats.welfare<50)effects.trust-=2;else if(state.stats.welfare>68)effects.trust+=1;if(state.stats.trust<32)effects.order-=2;if(state.stats.supply<30){effects.welfare-=3;effects.order-=2;}else if(state.stats.supply>72){effects.welfare+=1;effects.trust+=1;}
 const roll=Math.random();if(roll<.25)effects.supply+=3;else if(roll>.82)effects.supply-=2;addStats(effects);state.history.push({day:state.day,effects:{...effects},stats:{...state.stats}});state.day++;state.used=[];state.bulletins=0;messageClock=15;state.currentEvent=eventPool[(state.day-2+eventPool.length)%eventPool.length];const report=`Shift closed. Public order ${state.stats.order>=prior.order?'held':'slipped'}; reserve ${effects.supply<=-3?'fell':'was replenished'} ${Math.abs(effects.supply)} points. The district is watching.`;addMessage(makeMsg('ada',report,{channel:'civic',system:true,custom:true}),false);if(state.day>7||Object.values(state.stats).some(v=>v<=0)){state.ended=true;}render();save();$('#message-list').scrollTop=$('#message-list').scrollHeight;showToast(state.ended?'The final report is ready.':'Shift closed · the district has moved on.');if(state.ended)showEnding();else{setTimeout(autonomousMessage,700);setTimeout(autonomousMessage,1800);}}
function showEnding(){const score=Math.round((state.stats.order+state.stats.welfare+state.stats.trust+state.stats.supply)/4);let title,copy;if(state.stats.welfare<20||state.stats.order<18){title='The district broke its rhythm.';copy='The systems stopped working for the people they were meant to serve. It was never one decision alone; the small costs compounded.';}else if(score>=70){title='A city, held together.';copy='The district is not perfect, but its people are fed, heard, and looking out for one another. Your mandate ends with room to build.';}else if(state.stats.trust<25){title='Order without consent.';copy='The streets are quiet, but the district has learned not to expect an answer. Stability is not the same thing as belonging.';}else if(state.stats.welfare<30){title='The reserve ran out.';copy='People made do until they could not. The district will remember what was rationed, and who waited.';}else{title='The district carries on.';copy='Some systems held; others need more than a week to mend. The residents will keep talking. What happens next is still theirs to shape.';}$('#modal-kicker').textContent='END OF MANDATE · DISTRICT 17';$('#modal-title').textContent=title;$('#modal-content').innerHTML=`<div class="modal-copy"><p>${copy}</p><p><strong>Final district index: ${score}/100</strong></p><p>Order ${state.stats.order} · Welfare ${state.stats.welfare} · Trust ${state.stats.trust} · Reserve ${state.stats.supply}</p><p>Your choices are saved on this device. Restart from the ↻ control to try another approach.</p></div>`;$('#modal-primary').innerHTML='REVIEW THE DISTRICT <span>→</span>';$('#modal-primary').onclick=closeModal;$('#modal-backdrop').classList.add('open');$('#modal-backdrop').setAttribute('aria-hidden','false');}
function openHelp(){ $('#modal-kicker').textContent='FIELD TERMINAL GUIDE';$('#modal-title').textContent='The district is listening.';$('#modal-content').innerHTML='<div class="modal-copy"><p>You have <strong>seven shifts</strong> to keep District 17 functioning. Each shift gives you three directives and two public bulletins.</p><p><strong>Every choice has a cost.</strong> Patrols can improve order but erode trust. An assembly can build trust while making the streets less predictable. Supplies are finite.</p><p>Residents speak up on the district wire. Messages change with conditions, and they react to your decisions and bulletins. Watch for patterns before you act.</p><p>There is no perfect ending. The mandate asks you to leave a district where people can keep going.</p></div>';$ ('#modal-primary').innerHTML='UNDERSTOOD <span>→</span>';$('#modal-primary').onclick=closeModal;$('#modal-backdrop').classList.add('open');$('#modal-backdrop').setAttribute('aria-hidden','false');}
function closeModal(){$('#modal-backdrop').classList.remove('open');$('#modal-backdrop').setAttribute('aria-hidden','true');}
function restart(){if(!confirm('Restart District 17 and erase this local simulation?'))return;state=initialState();state.feed=seedFeed();activeChannel='all';save();updateChannel();render();showToast('New simulation started. The district is listening.');}
